recipes.code:
{
  "inputs": [
    {
      "id": "evm-private-key",
      "type": "promptString",
      "description": "Base (EVM) wallet private key (0x...) that funds x402 payments. One of EVM/SVM required for paid tools.",
      "password": true
    },
    {
      "id": "svm-private-key",
      "type": "promptString",
      "description": "Solana wallet secret key (base58) that funds x402 payments. One of EVM/SVM required for paid tools.",
      "password": true
    }
  ],
  "servers": {
    "telemost": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "telemost-mcp-server@0.2.2"
      ],
      "env": {
        "EVM_PRIVATE_KEY": "${input:evm-private-key}",
        "SVM_PRIVATE_KEY": "${input:svm-private-key}",
        "TELEMOST_BASE_URL": "<telemost-base-url>",
        "MAX_PAYMENT_USDC": "<max-payment-usdc>",
        "SESSION_MAX_USDC": "<session-max-usdc>"
      }
    }
  }
}
